-- =============================================================================
-- Swapiki — seed 56 DUMMY "Indian" candidate profiles (IT + BFSI)
-- Run this once in Supabase Dashboard > SQL Editor (test DB first).
--
-- WHAT THIS DOES
--   1. Add / ensures a hidden `is_dummy boolean` tag on `candidates`.
--      This tag is NEVER read by the app UI — it exists only for database
--      admins to identify and batch-delete demo rows later.
--   2. Insert 56 published candidate rows with realistic Indian names, roles
--      (34 IT, 22 BFSI), locations and skills. profile_status = 'published'
--      so they show up in the recruiter directory and public share links.
--      They have NO user_id (no real auth user) and NO contact details.
--
-- PHOTOS
--   The repo ships generated flat-style avatars at photos/dummy/<id>.svg and
--   set_dummy_avatars.sql points each dummy profile's `avatar` at its file
--   (run it right after this file, and once after the site is deployed so the
--   image files are live). To use real AI photos later, just overwrite the
--   matching file in photos/dummy/ with the same filename.
--
-- VERIFY / MASS-DELETE LATER
--   select count(*) from public.candidates where is_dummy = true;
--   select *  from public.candidates where is_dummy = true order by id;
--   delete from public.candidates where is_dummy = true;   -- batch delete
--
-- Idempotent: re-running it never duplicates rows (ON CONFLICT DO NOTHING).
-- =============================================================================

-- 1. Hidden admin tag.
alter table public.candidates
  add column if not exists is_dummy boolean not null default false;

comment on column public.candidates.is_dummy is
  'Admin-only flag: marks seeded/demo profiles. Never shown in the app UI. Use to filter and bulk-delete demo data before launch.';

-- 2. The 56 dummy profiles.
insert into public.candidates
  (id, username, name, title, experience, location, bio, expertise,
   status, profile_status, completion_score, views, shares, audio_listen_rate,
   voice_verified, updated_at)
values
