-- 3. Verify.
select
  count(*) filter (where is_dummy)            as dummy_profiles,
  count(*) filter (where expertise && array['React','Java','Python','AWS']::text[]) as rough_it_count,
  count(*)                                     as total_published
from public.candidates
where profile_status = 'published';